// Heartbeat implements mm_service.WatchProgress
func (mmHeartbeat *WatchProgressMock) Heartbeat(ctx context.Context, accountID uuid.UUID, groupID uuid.UUID, initiatorID uuid.UUID, videoID uuid.UUID, in domain.Heartbeat) (w1 domain.WatchState, err error) {
	mm_atomic.AddUint64(&mmHeartbeat.beforeHeartbeatCounter, 1)
	defer mm_atomic.AddUint64(&mmHeartbeat.afterHeartbeatCounter, 1)

	mmHeartbeat.t.Helper()

	if mmHeartbeat.inspectFuncHeartbeat != nil {
		mmHeartbeat.inspectFuncHeartbeat(ctx, accountID, groupID, initiatorID, videoID, in)
	}

	mm_params := WatchProgressMockHeartbeatParams{ctx, accountID, groupID, initiatorID, videoID, in}

	// Record call args
	mmHeartbeat.HeartbeatMock.mutex.Lock()
	mmHeartbeat.HeartbeatMock.callArgs = append(mmHeartbeat.HeartbeatMock.callArgs, &mm_params)
	mmHeartbeat.HeartbeatMock.mutex.Unlock()

	for _, e := range mmHeartbeat.HeartbeatMock.expectations {
		if minimock.Equal(*e.params, mm_params) {
			mm_atomic.AddUint64(&e.Counter, 1)
			return e.results.w1, e.results.err
		}
	}

	if mmHeartbeat.HeartbeatMock.defaultExpectation != nil {
		mm_atomic.AddUint64(&mmHeartbeat.HeartbeatMock.defaultExpectation.Counter, 1)
		mm_want := mmHeartbeat.HeartbeatMock.defaultExpectation.params
		mm_want_ptrs := mmHeartbeat.HeartbeatMock.defaultExpectation.paramPtrs

		mm_got := WatchProgressMockHeartbeatParams{ctx, accountID, groupID, initiatorID, videoID, in}

		if mm_want_ptrs != nil {

			if mm_want_ptrs.ctx != nil && !minimock.Equal(*mm_want_ptrs.ctx, mm_got.ctx) {
				mmHeartbeat.t.Errorf("WatchProgressMock.Heartbeat got unexpected parameter ctx, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
					mmHeartbeat.HeartbeatMock.defaultExpectation.expectationOrigins.originCtx, *mm_want_ptrs.ctx, mm_got.ctx, minimock.Diff(*mm_want_ptrs.ctx, mm_got.ctx))
			}

			if mm_want_ptrs.accountID != nil && !minimock.Equal(*mm_want_ptrs.accountID, mm_got.accountID) {
				mmHeartbeat.t.Errorf("WatchProgressMock.Heartbeat got unexpected parameter accountID, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
					mmHeartbeat.HeartbeatMock.defaultExpectation.expectationOrigins.originAccountID, *mm_want_ptrs.accountID, mm_got.accountID, minimock.Diff(*mm_want_ptrs.accountID, mm_got.accountID))
			}

			if mm_want_ptrs.groupID != nil && !minimock.Equal(*mm_want_ptrs.groupID, mm_got.groupID) {
				mmHeartbeat.t.Errorf("WatchProgressMock.Heartbeat got unexpected parameter groupID, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
					mmHeartbeat.HeartbeatMock.defaultExpectation.expectationOrigins.originGroupID, *mm_want_ptrs.groupID, mm_got.groupID, minimock.Diff(*mm_want_ptrs.groupID, mm_got.groupID))
			}

			if mm_want_ptrs.initiatorID != nil && !minimock.Equal(*mm_want_ptrs.initiatorID, mm_got.initiatorID) {
				mmHeartbeat.t.Errorf("WatchProgressMock.Heartbeat got unexpected parameter initiatorID, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
					mmHeartbeat.HeartbeatMock.defaultExpectation.expectationOrigins.originInitiatorID, *mm_want_ptrs.initiatorID, mm_got.initiatorID, minimock.Diff(*mm_want_ptrs.initiatorID, mm_got.initiatorID))
			}

			if mm_want_ptrs.videoID != nil && !minimock.Equal(*mm_want_ptrs.videoID, mm_got.videoID) {
				mmHeartbeat.t.Errorf("WatchProgressMock.Heartbeat got unexpected parameter videoID, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
					mmHeartbeat.HeartbeatMock.defaultExpectation.expectationOrigins.originVideoID, *mm_want_ptrs.videoID, mm_got.videoID, minimock.Diff(*mm_want_ptrs.videoID, mm_got.videoID))
			}

			if mm_want_ptrs.in != nil && !minimock.Equal(*mm_want_ptrs.in, mm_got.in) {
				mmHeartbeat.t.Errorf("WatchProgressMock.Heartbeat got unexpected parameter in, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
					mmHeartbeat.HeartbeatMock.defaultExpectation.expectationOrigins.originIn, *mm_want_ptrs.in, mm_got.in, minimock.Diff(*mm_want_ptrs.in, mm_got.in))
			}

		} else if mm_want != nil && !minimock.Equal(*mm_want, mm_got) {
			mmHeartbeat.t.Errorf("WatchProgressMock.Heartbeat got unexpected parameters, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
				mmHeartbeat.HeartbeatMock.defaultExpectation.expectationOrigins.origin, *mm_want, mm_got, minimock.Diff(*mm_want, mm_got))
		}

		mm_results := mmHeartbeat.HeartbeatMock.defaultExpectation.results
		if mm_results == nil {
			mmHeartbeat.t.Fatal("No results are set for the WatchProgressMock.Heartbeat")
		}
		return (*mm_results).w1, (*mm_results).err
	}
	if mmHeartbeat.funcHeartbeat != nil {
		return mmHeartbeat.funcHeartbeat(ctx, accountID, groupID, initiatorID, videoID, in)
	}
	mmHeartbeat.t.Fatalf("Unexpected call to WatchProgressMock.Heartbeat. %v %v %v %v %v %v", ctx, accountID, groupID, initiatorID, videoID, in)
	return
}

