func (mmOnDurationKnown *mWatchProgressMockOnDurationKnown) When(ctx context.Context, videoID uuid.UUID, durationMs int64) *WatchProgressMockOnDurationKnownExpectation {
	if mmOnDurationKnown.mock.funcOnDurationKnown != nil {
		mmOnDurationKnown.mock.t.Fatalf("WatchProgressMock.OnDurationKnown mock is already set by Set")
	}

	expectation := &WatchProgressMockOnDurationKnownExpectation{
		mock:               mmOnDurationKnown.mock,
		params:             &WatchProgressMockOnDurationKnownParams{ctx, videoID, durationMs},
		expectationOrigins: WatchProgressMockOnDurationKnownExpectationOrigins{origin: minimock.CallerInfo(1)},
	}
	mmOnDurationKnown.expectations = append(mmOnDurationKnown.expectations, expectation)
	return expectation
}

// Then sets up WatchProgress.OnDurationKnown return parameters for the expectation previously defined by the When method
func (e *WatchProgressMockOnDurationKnownExpectation) Then(err error) *WatchProgressMock {
	e.results = &WatchProgressMockOnDurationKnownResults{err}
	return e.mock
}

// Times sets number of times WatchProgress.OnDurationKnown should be invoked
func (mmOnDurationKnown *mWatchProgressMockOnDurationKnown) Times(n uint64) *mWatchProgressMockOnDurationKnown {
	if n == 0 {
		mmOnDurationKnown.mock.t.Fatalf("Times of WatchProgressMock.OnDurationKnown mock can not be zero")
	}
	mm_atomic.StoreUint64(&mmOnDurationKnown.expectedInvocations, n)
	mmOnDurationKnown.expectedInvocationsOrigin = minimock.CallerInfo(1)
	return mmOnDurationKnown
}

func (mmOnDurationKnown *mWatchProgressMockOnDurationKnown) invocationsDone() bool {
	if len(mmOnDurationKnown.expectations) == 0 && mmOnDurationKnown.defaultExpectation == nil && mmOnDurationKnown.mock.funcOnDurationKnown == nil {
		return true
	}

	totalInvocations := mm_atomic.LoadUint64(&mmOnDurationKnown.mock.afterOnDurationKnownCounter)
	expectedInvocations := mm_atomic.LoadUint64(&mmOnDurationKnown.expectedInvocations)

	return totalInvocations > 0 && (expectedInvocations == 0 || expectedInvocations == totalInvocations)
}

// OnDurationKnown implements mm_service.WatchProgress
func (mmOnDurationKnown *WatchProgressMock) OnDurationKnown(ctx context.Context, videoID uuid.UUID, durationMs int64) (err error) {
	mm_atomic.AddUint64(&mmOnDurationKnown.beforeOnDurationKnownCounter, 1)
	defer mm_atomic.AddUint64(&mmOnDurationKnown.afterOnDurationKnownCounter, 1)

	mmOnDurationKnown.t.Helper()

	if mmOnDurationKnown.inspectFuncOnDurationKnown != nil {
		mmOnDurationKnown.inspectFuncOnDurationKnown(ctx, videoID, durationMs)
	}

	mm_params := WatchProgressMockOnDurationKnownParams{ctx, videoID, durationMs}

	// Record call args
	mmOnDurationKnown.OnDurationKnownMock.mutex.Lock()
	mmOnDurationKnown.OnDurationKnownMock.callArgs = append(mmOnDurationKnown.OnDurationKnownMock.callArgs, &mm_params)
	mmOnDurationKnown.OnDurationKnownMock.mutex.Unlock()

	for _, e := range mmOnDurationKnown.OnDurationKnownMock.expectations {
		if minimock.Equal(*e.params, mm_params) {
			mm_atomic.AddUint64(&e.Counter, 1)
			return e.results.err
		}
	}

	if mmOnDurationKnown.OnDurationKnownMock.defaultExpectation != nil {
		mm_atomic.AddUint64(&mmOnDurationKnown.OnDurationKnownMock.defaultExpectation.Counter, 1)
		mm_want := mmOnDurationKnown.OnDurationKnownMock.defaultExpectation.params
		mm_want_ptrs := mmOnDurationKnown.OnDurationKnownMock.defaultExpectation.paramPtrs

		mm_got := WatchProgressMockOnDurationKnownParams{ctx, videoID, durationMs}

		if mm_want_ptrs != nil {

			if mm_want_ptrs.ctx != nil && !minimock.Equal(*mm_want_ptrs.ctx, mm_got.ctx) {
				mmOnDurationKnown.t.Errorf("WatchProgressMock.OnDurationKnown got unexpected parameter ctx, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
					mmOnDurationKnown.OnDurationKnownMock.defaultExpectation.expectationOrigins.originCtx, *mm_want_ptrs.ctx, mm_got.ctx, minimock.Diff(*mm_want_ptrs.ctx, mm_got.ctx))
			}

			if mm_want_ptrs.videoID != nil && !minimock.Equal(*mm_want_ptrs.videoID, mm_got.videoID) {
				mmOnDurationKnown.t.Errorf("WatchProgressMock.OnDurationKnown got unexpected parameter videoID, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
					mmOnDurationKnown.OnDurationKnownMock.defaultExpectation.expectationOrigins.originVideoID, *mm_want_ptrs.videoID, mm_got.videoID, minimock.Diff(*mm_want_ptrs.videoID, mm_got.videoID))
			}

			if mm_want_ptrs.durationMs != nil && !minimock.Equal(*mm_want_ptrs.durationMs, mm_got.durationMs) {
				mmOnDurationKnown.t.Errorf("WatchProgressMock.OnDurationKnown got unexpected parameter durationMs, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
					mmOnDurationKnown.OnDurationKnownMock.defaultExpectation.expectationOrigins.originDurationMs, *mm_want_ptrs.durationMs, mm_got.durationMs, minimock.Diff(*mm_want_ptrs.durationMs, mm_got.durationMs))
			}

		} else if mm_want != nil && !minimock.Equal(*mm_want, mm_got) {
			mmOnDurationKnown.t.Errorf("WatchProgressMock.OnDurationKnown got unexpected parameters, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
				mmOnDurationKnown.OnDurationKnownMock.defaultExpectation.expectationOrigins.origin, *mm_want, mm_got, minimock.Diff(*mm_want, mm_got))
		}

		mm_results := mmOnDurationKnown.OnDurationKnownMock.defaultExpectation.results
		if mm_results == nil {
			mmOnDurationKnown.t.Fatal("No results are set for the WatchProgressMock.OnDurationKnown")
		}
		return (*mm_results).err
	}
	if mmOnDurationKnown.funcOnDurationKnown != nil {
		return mmOnDurationKnown.funcOnDurationKnown(ctx, videoID, durationMs)
	}
	mmOnDurationKnown.t.Fatalf("Unexpected call to WatchProgressMock.OnDurationKnown. %v %v %v", ctx, videoID, durationMs)
	return
}

// OnDurationKnownAfterCounter returns a count of finished WatchProgressMock.OnDurationKnown invocations
func (mmOnDurationKnown *WatchProgressMock) OnDurationKnownAfterCounter() uint64 {
	return mm_atomic.LoadUint64(&mmOnDurationKnown.afterOnDurationKnownCounter)
}

// OnDurationKnownBeforeCounter returns a count of WatchProgressMock.OnDurationKnown invocations
func (mmOnDurationKnown *WatchProgressMock) OnDurationKnownBeforeCounter() uint64 {
	return mm_atomic.LoadUint64(&mmOnDurationKnown.beforeOnDurationKnownCounter)
}

// Calls returns a list of arguments used in each call to WatchProgressMock.OnDurationKnown.
// The list is in the same order as the calls were made (i.e. recent calls have a higher index)
func (mmOnDurationKnown *mWatchProgressMockOnDurationKnown) Calls() []*WatchProgressMockOnDurationKnownParams {
	mmOnDurationKnown.mutex.RLock()

	argCopy := make([]*WatchProgressMockOnDurationKnownParams, len(mmOnDurationKnown.callArgs))
	copy(argCopy, mmOnDurationKnown.callArgs)

	mmOnDurationKnown.mutex.RUnlock()

	return argCopy
}

// MinimockOnDurationKnownDone returns true if the count of the OnDurationKnown invocations corresponds
// the number of defined expectations
func (m *WatchProgressMock) MinimockOnDurationKnownDone() bool {
	if m.OnDurationKnownMock.optional {
		// Optional methods provide '0 or more' call count restriction.
		return true
	}

	for _, e := range m.OnDurationKnownMock.expectations {
		if mm_atomic.LoadUint64(&e.Counter) < 1 {
			return false
		}
	}

	return m.OnDurationKnownMock.invocationsDone()
}

// MinimockOnDurationKnownInspect logs each unmet expectation
func (m *WatchProgressMock) MinimockOnDurationKnownInspect() {
	for _, e := range m.OnDurationKnownMock.expectations {
		if mm_atomic.LoadUint64(&e.Counter) < 1 {
			m.t.Errorf("Expected call to WatchProgressMock.OnDurationKnown at\n%s with params: %#v", e.expectationOrigins.origin, *e.params)
		}
	}

	afterOnDurationKnownCounter := mm_atomic.LoadUint64(&m.afterOnDurationKnownCounter)
	// if default expectation was set then invocations count should be greater than zero
	if m.OnDurationKnownMock.defaultExpectation != nil && afterOnDurationKnownCounter < 1 {
		if m.OnDurationKnownMock.defaultExpectation.params == nil {
			m.t.Errorf("Expected call to WatchProgressMock.OnDurationKnown at\n%s", m.OnDurationKnownMock.defaultExpectation.returnOrigin)
		} else {
			m.t.Errorf("Expected call to WatchProgressMock.OnDurationKnown at\n%s with params: %#v", m.OnDurationKnownMock.defaultExpectation.expectationOrigins.origin, *m.OnDurationKnownMock.defaultExpectation.params)
		}
	}
	// if func was set then invocations count should be greater than zero
	if m.funcOnDurationKnown != nil && afterOnDurationKnownCounter < 1 {
		m.t.Errorf("Expected call to WatchProgressMock.OnDurationKnown at\n%s", m.funcOnDurationKnownOrigin)
	}

	if !m.OnDurationKnownMock.invocationsDone() && afterOnDurationKnownCounter > 0 {
		m.t.Errorf("Expected %d calls to WatchProgressMock.OnDurationKnown at\n%s but found %d calls",
			mm_atomic.LoadUint64(&m.OnDurationKnownMock.expectedInvocations), m.OnDurationKnownMock.expectedInvocationsOrigin, afterOnDurationKnownCounter)
	}
}

// MinimockFinish checks that all mocked methods have been called the expected number of times
func (m *WatchProgressMock) MinimockFinish() {
	m.finishOnce.Do(func() {
		if !m.minimockDone() {
			m.MinimockGetInspect()

			m.MinimockHeartbeatInspect()

			m.MinimockOnDurationKnownInspect()
		}
	})
}

// MinimockWait waits for all mocked methods to be called the expected number of times
func (m *WatchProgressMock) MinimockWait(timeout mm_time.Duration) {
	timeoutCh := mm_time.After(timeout)
	for {
		if m.minimockDone() {
			return
		}
		select {
		case <-timeoutCh:
			m.MinimockFinish()
			return
		case <-mm_time.After(10 * mm_time.Millisecond):
		}
	}
}

func (m *WatchProgressMock) minimockDone() bool {
	done := true
	return done &&
		m.MinimockGetDone() &&
		m.MinimockHeartbeatDone() &&
		m.MinimockOnDurationKnownDone()
}
